// Room: Coop nest room (interior designer's part). Inner air x64..67, y2..4, z13..15 (rooms.json box [64,2,13,67,4,15]).
// Focal piece: the nest row against the back wall (z15), facing the chicken door: hay_block and barrels alternating.
// Light: one standing lantern on the barrel at x65 (level 10+ over the whole room). The floor is the coop shell's spruce
// at y1, so no straw is laid on y2: a full block there would take the walk height from y2 to y3.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Layer y2 (floor level) then y3 (the lantern). Rows run along +x from x64, successive rows along +z from z13.
  layers(g, [64, 2, 13], {
    h: "hay_block",
    b: ["barrel", { facing: "up" }],
  }, [
    ["    ", "    ", "hbhb"],   // y2: z13, z14 clear floor; z15 nest row
    ["    ", "    ", " l  "],   // y3: lantern standing on the barrel at x65, z15
  ]);
}

